import {
  ChangeDetectionStrategy,
  Component,
  computed,
  input,
  ViewEncapsulation,
} from '@angular/core';
import { cn } from '@gremorie/ng-core';
import { cva, type VariantProps } from 'class-variance-authority';

import {
  buildQrMatrix,
  QR_QUIET_ZONE,
  type QrCodeEcc,
  type QrCodeMatrix,
} from './qr-code.logic';

/**
 * QrCode variants: mirrors React `qrCodeVariants` from `@gremorie/rx-display`
 * (class strings copied verbatim).
 */
export const qrCodeVariants = cva(
  'relative inline-flex shrink-0 overflow-hidden rounded-xl bg-gray-50 text-gray-950',
  {
    variants: {
      size: {
        sm: 'size-32',
        md: 'size-48',
        lg: 'size-64',
      },
    },
    defaultVariants: { size: 'md' },
  },
);

export type QrCodeSize = NonNullable<
  VariantProps<typeof qrCodeVariants>['size']
>;

/**
 * QrCode: a scannable code drawn as one SVG path, so color comes from tokens.
 * Mirrors React `QrCode` from `@gremorie/rx-display`.
 *
 * The matrix is built by `uqr` (value + error correction level) and the dark
 * modules are painted with `currentColor`: dark modules on a light plate
 * (`text-gray-950` on `bg-gray-50`) in every theme, because many camera
 * readers fail on an inverted code. The four-module quiet zone scanners need
 * kept inside the box. Project a mark as content to center it over the code;
 * raise `ecc` to `Q` or `H` when it covers more than a small mark.
 *
 * @example
 * ```html
 * <gr-qr-code value="https://example.com/link/42" aria-label="Pairing code" />
 * ```
 */
@Component({
  selector: 'gr-qr-code',
  standalone: true,
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    @if (matrix(); as m) {
      <svg
        aria-hidden="true"
        class="size-full"
        shape-rendering="crispEdges"
        [attr.viewBox]="viewBox()"
      >
        <path [attr.d]="m.path" fill="currentColor" />
      </svg>
    }
    <span
      data-slot="qr-code-icon"
      class="absolute inset-0 m-auto flex size-1/5 items-center justify-center rounded-md bg-gray-50 empty:hidden [&_svg]:size-full"
      ><ng-content
    /></span>
  `,
  host: {
    'data-slot': 'qr-code',
    role: 'img',
    '[attr.aria-label]': 'ariaLabel()',
    '[attr.data-ecc]': 'ecc()',
    '[attr.data-modules]': 'matrix()?.modules',
    '[class]': 'mergedClass()',
  },
})
export class QrCode {
  /** Extra classes merged over the defaults via `cn`. Mirrors React `className`. */
  readonly class = input<string>();

  /** Text the code encodes, usually a URL. */
  readonly value = input.required<string>();
  /** Error correction level: L ~7%, M ~15%, Q ~25%, H ~30%. */
  readonly ecc = input<QrCodeEcc>('M');
  readonly size = input<QrCodeSize>('md');
  /** Accessible name of the code. Mirrors React `aria-label`. */
  readonly ariaLabel = input<string>('QR code', { alias: 'aria-label' });

  protected readonly matrix = computed<QrCodeMatrix | null>(() => {
    try {
      return buildQrMatrix(this.value(), this.ecc());
    } catch {
      // Value longer than the largest code can hold: render an empty box.
      return null;
    }
  });

  protected readonly viewBox = computed(() => {
    const m = this.matrix();
    const span = m ? m.size + QR_QUIET_ZONE * 2 : 0;
    return `${-QR_QUIET_ZONE} ${-QR_QUIET_ZONE} ${span} ${span}`;
  });

  protected readonly mergedClass = computed(() =>
    cn(qrCodeVariants({ size: this.size() }), this.class()),
  );
}

import { encode } from 'uqr';

/** Error correction level: L ~7%, M ~15%, Q ~25%, H ~30% recoverable. */
export type QrCodeEcc = 'L' | 'M' | 'Q' | 'H';

export interface QrCodeMatrix {
  /** Modules per side (quiet zone not included). */
  size: number;
  /** Number of dark modules. */
  modules: number;
  /** One SVG path covering every dark module, in module units. */
  path: string;
}

/**
 * Quiet zone, in modules, kept clear on every side. The QR specification asks
 * for four; scanners lose the code below that.
 */
export const QR_QUIET_ZONE = 4;

/**
 * Encode `value` with `uqr` and fold the dark modules into a single path:
 * horizontal runs of adjacent modules become one `h` segment each, which keeps
 * the markup small and avoids hairline gaps between neighbouring squares.
 *
 * Mirrors `packages/rx-display/src/lib/qr-code/qr-code.logic.ts`; both
 * editions must produce the same matrix and path for the same input.
 */
export function buildQrMatrix(
  value: string,
  ecc: QrCodeEcc = 'M',
): QrCodeMatrix {
  const { data, size } = encode(value, { ecc, border: 0 });
  let modules = 0;
  let path = '';
  for (let y = 0; y < size; y++) {
    let x = 0;
    while (x < size) {
      if (!data[y][x]) {
        x++;
        continue;
      }
      const start = x;
      while (x < size && data[y][x]) x++;
      modules += x - start;
      path += `M${start} ${y}h${x - start}v1h-${x - start}z`;
    }
  }
  return { size, modules, path };
}
